// Textures: loading, flags, filters and the layers of a texture.

#include "graphics_internal.hpp"

using namespace bb::gfx;

namespace bb::gfx {

	texture_entry* texture_of(int handle)
	{
		if ((handle < 1) || (uint32_t(handle) > texture_table.size) || !texture_table[uint32_t(handle) - 1].used) {
			return nullptr;
		}
		return &texture_table[uint32_t(handle) - 1];
	}

	void free_image(image_entry& e)
	{
		if (g.device && e.set) {
			flush(); // What was asked to be drawn with it comes first.
			vkDeviceWaitIdle(g.device);
			vkFreeDescriptorSets(g.device, g.set_pool, 1, &e.set);
			destroy_image(e.image);
		}
		free(e.solid);
		e = image_entry();
	}

	void free_texture(texture_entry& t)
	{
		if (g.device && t.set) {
			flush(); // What was asked to be drawn with it comes first.
			vkDeviceWaitIdle(g.device);
			vkFreeDescriptorSets(g.device, g.set_pool, 1, &t.set);
			destroy_image(t.image);
		}
		t = texture_entry();
	}
	static bb::buffer<texture_filter> texture_filters;

	////////////////////////////////////////////////////////////////////////////////
	// Textures, a little more
	////////////////////////////////////////////////////////////////////////////////
	static texture_entry* need_texture(int32_t handle, const char* what)
	{
		texture_entry* t = texture_of(handle);
		if (!t) {
			char message[96];
			snprintf(message, sizeof(message), "%s: the texture does not exist.", what);
			bb_runtime_error(message);
		}
		return t;
	}
} // namespace bb::gfx

extern "C" {

int32_t bb_color_blue(void)
{
	return g.color[2];
}

// CreateTexture(width, height, flags, frames): an empty texture to draw on, with TextureBuffer.
int32_t bb_create_texture(int32_t width, int32_t height, int32_t flags, int32_t frames)
{
	(void)frames;
	if ((width <= 0) || (height <= 0)) {
		bb_runtime_error("CreateTexture: needs a size.");
	}
	texture_entry entry;
	entry.used   = true;
	entry.flags  = flags;
	entry.width  = width;
	entry.height = height;
	if (active()) {
		uint8_t* pixels = static_cast<uint8_t*>(calloc(size_t(width) * size_t(height), 4));
		for (size_t i = 0; i < size_t(width) * size_t(height); i++) {
			pixels[i * 4 + 3] = 255;
		}
		VkSampler sampler = ((flags & TEXTURE_CLAMP_U) || (flags & TEXTURE_CLAMP_V)) ? g.sampler_clamp : g.sampler_repeat;
		upload_texture(entry.image, entry.set, uint32_t(width), uint32_t(height), pixels, sampler);
		free(pixels);
	}
	for (uint32_t i = 0; i < texture_table.size; i++) {
		if (!texture_table[i].used) {
			texture_table[i] = entry;
			return int32_t(i) + 1;
		}
	}
	texture_table.push(entry);
	return int32_t(texture_table.size);
}

int32_t bb_filter_texture_flags(const char* file, int32_t flags)
{
	if (!file) {
		return flags;
	}
	size_t length = strlen(file);
	char*  lower  = static_cast<char*>(malloc(length + 1));
	for (size_t i = 0; i <= length; i++) {
		char c   = file[i];
		lower[i] = (c >= 'A' && c <= 'Z') ? char(c + 32) : c;
	}
	for (uint32_t i = 0; i < texture_filters.size; i++) {
		if (strstr(lower, texture_filters[i].match)) {
			flags |= texture_filters[i].flags;
		}
	}
	free(lower);
	return flags;
}

// Loads a texture with exactly these flags. Where alpha comes from is what the original does: nothing, if the flag is
// not there, and with it the alpha channel of the image if it has one, and otherwise how bright each pixel is.
int32_t bb_load_texture_flags(const char* file, int32_t flags)
{
	if (!file) {
		return 0;
	}
	if (flags & TEXTURE_MASKED) {
		flags |= 1 | TEXTURE_ALPHA;
	}
	SDL_Surface* loaded = IMG_Load(file);
	if (!loaded) {
		return 0; // Blitz gives 0 for missing files.
	}
	bool         has_alpha = SDL_ISPIXELFORMAT_ALPHA(loaded->format);
	SDL_Surface* rgba      = SDL_ConvertSurface(loaded, SDL_PIXELFORMAT_RGBA32);
	SDL_DestroySurface(loaded);
	if (!rgba) {
		return 0;
	}

	// Pictures with a palette can have see-through colors, which only shows once they are converted.
	if (!has_alpha) {
		for (int y = 0; y < rgba->h && !has_alpha; y++) {
			const uint8_t* row = static_cast<const uint8_t*>(rgba->pixels) + size_t(y) * size_t(rgba->pitch);
			for (int x = 0; x < rgba->w; x++) {
				if (row[x * 4 + 3] != 255) {
					has_alpha = true;
					break;
				}
			}
		}
	}
	bool whiten = !(flags & 1); // Only alpha was asked for, so the picture has no color of its own.
	for (int y = 0; y < rgba->h; y++) {
		uint8_t* row = static_cast<uint8_t*>(rgba->pixels) + size_t(y) * size_t(rgba->pitch);
		for (int x = 0; x < rgba->w; x++) {
			uint8_t* px = row + x * 4;
			if (!(flags & TEXTURE_ALPHA)) {
				px[3] = 255;
			} else if (flags & TEXTURE_MASKED) {
				px[3] = (px[0] || px[1] || px[2]) ? 255 : 0; // Black is not there.
			} else if (!has_alpha) {
				px[3] = uint8_t((px[0] + px[1] + px[2]) / 3);
				if (whiten) {
					px[0] = px[1] = px[2] = 255;
				}
			}
		}
	}

	texture_entry entry;
	entry.used   = true;
	entry.flags  = flags;
	entry.width  = rgba->w;
	entry.height = rgba->h;
	if (active()) {
		VkSampler sampler = ((flags & TEXTURE_CLAMP_U) || (flags & TEXTURE_CLAMP_V)) ? g.sampler_clamp : g.sampler_repeat;
		upload_texture(entry.image, entry.set, uint32_t(rgba->w), uint32_t(rgba->h), static_cast<const uint8_t*>(rgba->pixels), sampler);
	}
	SDL_DestroySurface(rgba);

	for (uint32_t i = 0; i < texture_table.size; i++) {
		if (!texture_table[i].used) {
			texture_table[i] = entry;
			return int32_t(i) + 1;
		}
	}
	texture_table.push(entry);
	return int32_t(texture_table.size);
}

int32_t bb_load_texture(const char* file, int32_t flags)
{
	return bb_load_texture_flags(file, bb_filter_texture_flags(file, flags));
}

void bb_free_texture(int32_t handle)
{
	texture_entry* t = texture_of(handle);
	if (t) {
		free_texture(*t);
	}
}

int32_t bb_texture_width(int32_t handle)
{
	texture_entry* t = texture_of(handle);
	return t ? t->width : 0;
}

int32_t bb_texture_height(int32_t handle)
{
	texture_entry* t = texture_of(handle);
	return t ? t->height : 0;
}

// ScaleTexture makes the texture bigger for numbers above 1: the coordinates are divided.
void bb_scale_texture(int32_t handle, float u, float v)
{
	texture_entry* t = need_texture(handle, "ScaleTexture");
	t->uv[0]         = (u != 0) ? 1.0f / u : 1.0f;
	t->uv[1]         = (v != 0) ? 1.0f / v : 1.0f;
}

void bb_position_texture(int32_t handle, float u, float v)
{
	texture_entry* t = need_texture(handle, "PositionTexture");
	t->uv[2]         = u;
	t->uv[3]         = v;
}

// Rotating textures is not supported, the call is accepted so programs that do it still run.
void bb_rotate_texture(int32_t handle, float angle)
{
	(void)angle;
	need_texture(handle, "RotateTexture");
}

void bb_texture_blend(int32_t handle, int32_t mode)
{
	need_texture(handle, "TextureBlend")->blend = mode;
}

void bb_texture_filter(const char* match, int32_t flags)
{
	const char* text   = match ? match : "";
	size_t      length = strlen(text);
	char*       lower  = static_cast<char*>(malloc(length + 1));
	for (size_t i = 0; i <= length; i++) {
		char c   = text[i];
		lower[i] = (c >= 'A' && c <= 'Z') ? char(c + 32) : c;
	}
	texture_filters.push({ lower, flags });
}

void bb_set_cube_face(int32_t handle, int32_t face)
{
	(void)face;
	need_texture(handle, "SetCubeFace"); // Cube maps are not supported.
}
}
